"""User-facing reply text, generated by the application layer.

For control requests the reply is built from what the device control
service actually *accepted*, never from model-written prose. The model can
say what it intends to do; only the execution path can say what was done.

Wording is deliberate: "已下发" (dispatched) means the device control
service accepted the command. Device execution is confirmed asynchronously
through state reports and command receipts.
"""

from __future__ import annotations

from collections.abc import Iterable

from .catalog import actions_for
from .models import Device, DispatchResult, PlannedAction, SkippedDevice

FALLBACK_REPLY = "抱歉，这句话我没能理解，请换个说法再试一次。"
NOTHING_TO_DO_REPLY = "没有需要操作的设备。"

_ACTION_VERBS = {
    "turnOn": "打开",
    "turnOff": "关闭",
    "open": "打开",
    "close": "关闭",
    "lock": "锁上",
    "unlock": "解锁",
    "disarm": "撤防",
    "play": "播放",
    "pause": "暂停",
}


def describe_action(device: Device, act: PlannedAction) -> str:
    if act.action in _ACTION_VERBS:
        return f"{_ACTION_VERBS[act.action]}{device.name}"
    spec = actions_for(device.type).get(act.action)
    parts = []
    for p in spec.params if spec else ():
        if p.name in act.params:
            parts.append(f"{act.params[p.name]}{p.unit}")
    label = {
        "setBrightness": "亮度",
        "setColorTemperature": "色温",
        "setPosition": "开合度",
        "setTemperature": "温度",
        "setMode": "模式",
        "setVolume": "音量",
        "arm": "布防模式",
    }.get(act.action, act.action)
    return f"把{device.name}{label}调到{'、'.join(parts)}"


def _join(items: Iterable[str]) -> str:
    items = list(items)
    if len(items) <= 1:
        return "".join(items)
    return "、".join(items[:-1]) + "和" + items[-1]


def control_reply(
    whitelist: dict[str, Device],
    results: list[DispatchResult],
    held: list[PlannedAction],
    denied: list[PlannedAction],
    skipped: list[SkippedDevice],
    rejected_count: int,
    conflicts: list[str],
    ambiguous: str = "",
) -> str:
    ok = [r for r in results if r.accepted]
    failed = [r for r in results if not r.accepted]
    sentences: list[str] = []

    def dev(uuid: str) -> Device:
        return whitelist[uuid]

    if ok:
        sentences.append(
            "已下发指令："
            + _join(describe_action(dev(r.uuid), PlannedAction(r.uuid, r.action, r.params)) for r in ok)
        )
    if failed:
        sentences.append("下发失败：" + _join(dev(r.uuid).name for r in failed) + "，请稍后重试")
    if held:
        sentences.append(
            "需要你在 App 中确认后才会执行：" + _join(describe_action(dev(a.uuid), a) for a in held)
        )
    if denied:
        sentences.append(
            "出于安全考虑，以下操作不会执行：" + _join(describe_action(dev(a.uuid), a) for a in denied)
        )
    for s in skipped:
        sentences.append(f"{dev(s.uuid).name}保持当前状态（{s.reason}）")
    if conflicts:
        sentences.append(
            "对" + _join(dev(u).name for u in conflicts) + "的要求互相矛盾，请再说明一下想怎么操作"
        )
    if ambiguous:
        sentences.append(ambiguous)
    if rejected_count and not (ok or held or denied or ambiguous):
        sentences.append("有部分要求无法执行")
    if not sentences:
        return NOTHING_TO_DO_REPLY
    return "；".join(sentences) + "。"
